import { path } from '@servicenow/sdk-build-core'
import { createTestContext, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

/**
 * Round-Trip Test: comprehensive-flowobject-test
 *
 * XML Source: sys_hub_flow_57fff2c887d2496990087de5dd5d3888.xml
 * Fluent Source: set-flow-variables-object-array-example.now.ts
 *
 * Flow Name: Comprehensive Test - FlowObject and FlowArray
 * Description: Tests all possible cases for FlowObject and FlowArray in setFlowVariables
 *
 * Features Tested:
 * - Flow definition with FlowObject and FlowArray variables
 * - Record created trigger on incident table
 * - setFlowVariables logic with 15 TEST cases
 * - Complex nested structures (FlowObject within FlowObject, FlowArray within FlowObject)
 * - Data value validations (literals, datapills, empty/null values, template expressions)
 * - XML → Fluent → XML round-trip transformation
 */

/**
 * Helper function to validate imports in generated Fluent code
 * @param content - The Fluent code content to validate
 * @param expectedImports - Array of expected import strings
 */
function validateImports(content: string, expectedImports: string[]) {
    expect(content).toContain('import {')
    expectedImports.forEach((importName) => {
        expect(content).toContain(importName)
    })
}

describe('comprehensive-flowobject-test: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Test: set-flow-variables-object-array-example
     * XML: sys_hub_flow_57fff2c887d2496990087de5dd5d3888.xml
     * Type: Flow
     * Features: Scheduled trigger (daily), FlowObject and FlowArray variables, setFlowVariables logic
     */
    test('set-flow-variables-object-array-example: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_57fff2c887d2496990087de5dd5d3888.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Verify imports
        validateImports(fluentContent, [
            'Flow',
            'FlowObject',
            'FlowArray',
            'StringColumn',
            'IntegerColumn',
            'BooleanColumn',
            'trigger',
        ])

        // Verify flow definition
        expect(fluentContent).toContain('Flow(')
        expect(fluentContent).toContain("name: 'Comprehensive Test - FlowObject and FlowArray'")
        expect(fluentContent).toContain(
            "description: 'Tests all possible cases for FlowObject and FlowArray in setFlowVariables'"
        )

        // Verify flowVariables section
        expect(fluentContent).toContain('flowVariables: {')

        // Verify FlowObject variables with fields
        expect(fluentContent).toContain('userInfo: FlowObject(')
        expect(fluentContent).toContain('fields: {')
        expect(fluentContent).toContain('name: StringColumn(')
        expect(fluentContent).toContain('email: StringColumn(')
        expect(fluentContent).toContain('age: IntegerColumn(')
        expect(fluentContent).toContain('isActive: BooleanColumn(')

        // Verify FlowArray variables (tags is a FlowArray in the actual XML)
        expect(fluentContent).toContain('tags: FlowArray(')
        expect(fluentContent).toContain('elementType: FlowObject(')

        // Verify other FlowObject variables from XML
        expect(fluentContent).toContain('project: FlowObject(')
        expect(fluentContent).toContain('config: FlowObject(')

        // Verify trigger (record created on incident table)
        expect(fluentContent).toContain('wfa.trigger(')
        expect(fluentContent).toContain('trigger.record.created')

        // Verify setFlowVariables calls
        expect(fluentContent).toContain('wfa.flowLogic.setFlowVariables(')
        expect(fluentContent).toContain('_params.flowVariables')

        // Verify test annotations
        expect(fluentContent).toContain('TEST 1:')
        expect(fluentContent).toContain('TEST 2:')
        expect(fluentContent).toContain('TEST 3:')

        // Verify TEST 1 data values (literals)
        expect(fluentContent).toContain("name: 'John Doe'")
        expect(fluentContent).toContain("email: 'john.doe@example.com'")
        expect(fluentContent).toContain('age: 30')
        expect(fluentContent).toContain('isActive: true')
        expect(fluentContent).toContain("value: 'urgent'")
        expect(fluentContent).toContain("value: 'important'")
        expect(fluentContent).toContain("value: 'review'")
        expect(fluentContent).toContain("simpleString: 'Test completed'")

        // Verify TEST 2 data values (datapills)
        expect(fluentContent).toMatch(/wfa\.dataPill\(.*params\.trigger\.current\.assigned_to\.name/)
        expect(fluentContent).toMatch(/wfa\.dataPill\(.*params\.trigger\.current\.assigned_to\.email/)
        expect(fluentContent).toMatch(/wfa\.dataPill\(.*params\.trigger\.current\.number/)
        expect(fluentContent).toMatch(/wfa\.dataPill\(.*params\.trigger\.current\.business_impact/)

        // Verify TEST 3 data values (nested object literals)
        expect(fluentContent).toContain('timeout: 60')
        expect(fluentContent).toContain('retries: 5')
        expect(fluentContent).toContain('enabled: true')
        expect(fluentContent).toContain("description: 'Production configuration'")

        // Verify TEST 4 data values (nested object with datapills)
        expect(fluentContent).toMatch(/timeout:.*wfa\.dataPill\(.*params\.trigger\.current\.priority/)
        expect(fluentContent).toContain('retries: 3')
        expect(fluentContent).toMatch(/description:.*wfa\.dataPill\(.*params\.trigger\.current\.short_description/)

        // Verify TEST 5 data values (object with nested array)
        expect(fluentContent).toContain("name: 'Infrastructure Upgrade'")
        expect(fluentContent).toContain("taskName: 'Setup servers'")
        expect(fluentContent).toContain("taskName: 'Configure network'")
        expect(fluentContent).toContain("taskName: 'Deploy apps'")

        // Verify TEST 6 data values (empty and null values)
        expect(fluentContent).toContain("field1: 'Has value'")
        expect(fluentContent).toContain("field2: ''")
        expect(fluentContent).toContain("field3: ''")

        // Verify TEST 7 data values (primitive datapill to FlowObject)
        expect(fluentContent).toMatch(/callerData:.*wfa\.dataPill\(.*params\.trigger\.current\.caller_id/)

        // Verify TEST 8 data values (empty array)
        expect(fluentContent).toContain("item: ''")

        // Verify TEST 9 data values (mixed literals and datapills)
        expect(fluentContent).toContain("staticValue: 'Static literal value'")
        expect(fluentContent).toMatch(/dynamicValue:.*wfa\.dataPill\(.*params\.trigger\.current\.number/)
        expect(fluentContent).toMatch(/computedValue:.*Incident:.*wfa\.dataPill/)

        // Verify TEST 10 data values (template expressions)
        expect(fluentContent).toMatch(/name:.*User:.*wfa\.dataPill\(.*params\.trigger\.current\.caller_id/)
        expect(fluentContent).toMatch(/email:.*wfa\.dataPill\(.*params\.trigger\.current\.number.*@example\.com/)
        expect(fluentContent).toContain('age: 35')

        // Verify TEST 11 data values (datapills in array)
        expect(fluentContent).toMatch(/value:.*wfa\.dataPill\(.*params\.trigger\.current\.priority/)
        expect(fluentContent).toMatch(/value:.*wfa\.dataPill\(.*params\.trigger\.current\.state/)
        expect(fluentContent).toMatch(/value:.*Status:.*wfa\.dataPill\(.*params\.trigger\.current\.incident_state/)

        // Verify TEST 12 data values (array with mixed elements)
        expect(fluentContent).toContain("value: 'literal-tag-1'")
        expect(fluentContent).toMatch(/value:.*wfa\.dataPill\(.*params\.trigger\.current\.urgency/)
        expect(fluentContent).toContain("value: 'literal-tag-2'")
        expect(fluentContent).toMatch(/value:.*wfa\.dataPill\(.*params\.trigger\.current\.impact/)

        // Verify TEST 13 data values (all empty values)
        expect(fluentContent).toContain("field1: ''")
        expect(fluentContent).toContain("field2: ''")
        expect(fluentContent).toContain("field3: '")

        // Verify TEST 14 data values (identifier to FlowObject)
        expect(fluentContent).toMatch(/callerData:.*wfa\.dataPill\(.*params\.trigger\.current,/)

        // Verify TEST 15 data values (deeply nested property access)
        expect(fluentContent).toMatch(/timeout:.*wfa\.dataPill\(.*params\.trigger\.current\.priority/)
        expect(fluentContent).toMatch(/retries:.*wfa\.dataPill\(.*params\.trigger\.current\.urgency/)
        expect(fluentContent).toMatch(/enabled:.*wfa\.dataPill\(.*params\.trigger\.current\.active/)
        expect(fluentContent).toMatch(/description:.*wfa\.dataPill\(.*params\.trigger\.current\.short_description/)

        // Verify final log action
        expect(fluentContent).toContain("log_message: 'All FlowObject/FlowArray tests completed successfully'")

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)!.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        // Verify expected XML tables exist
        expect(mergedRecords['sys_hub_flow']).toBeDefined()
        expect(mergedRecords['sys_hub_trigger_instance_v2']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_variable']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_logic_instance_v2']).toBeDefined()

        // ============================================================================
        // Step 4: Validate Flow Record
        // ============================================================================
        const flows = mergedRecords['sys_hub_flow']
        expect(flows.length).toBeGreaterThanOrEqual(1)
        const flow = flows.find((f: any) => f.name === 'Comprehensive Test - FlowObject and FlowArray')
        expect(flow).toBeDefined()
        expect(flow.description).toBe('Tests all possible cases for FlowObject and FlowArray in setFlowVariables')
        expect(flow.type).toBe('flow')
        expect(flow.generation_source).toBe('fluent')
        expect(flow.run_as).toBe('system')

        // ============================================================================
        // Step 5: Validate Trigger (Record Created on Incident)
        // ============================================================================
        const triggerInstances = mergedRecords['sys_hub_trigger_instance_v2']
        expect(triggerInstances.length).toBeGreaterThan(0)
        const trigger = triggerInstances[0]
        expect(trigger).toBeDefined()

        // ============================================================================
        // Step 6: Validate Flow Variables
        // ============================================================================
        const flowVars = mergedRecords['sys_hub_flow_variable']
        expect(flowVars.length).toBeGreaterThan(5)

        // Verify userInfo FlowObject variable
        const userInfo = flowVars.find((v: any) => v.element === 'userInfo')
        expect(userInfo).toBeDefined()
        expect(userInfo.label).toBe('User Info')
        expect(userInfo.mandatory).toBe(false)
        expect(userInfo.active).toBe(true)

        // Verify tags FlowArray variable
        const tags = flowVars.find((v: any) => v.element === 'tags')
        expect(tags).toBeDefined()
        expect(tags.label).toBe('Tags')
        expect(tags.mandatory).toBe(false)
        expect(tags.active).toBe(true)

        // Verify config FlowObject variable
        const config = flowVars.find((v: any) => v.element === 'config')
        expect(config).toBeDefined()
        expect(config.label).toBe('Config')

        // Verify project FlowObject variable
        const projectVar = flowVars.find((v: any) => v.element === 'project')
        expect(projectVar).toBeDefined()
        expect(projectVar.label).toBe('Project')

        // ============================================================================
        // Step 7: Validate Flow Logic Data Values (Decompress and Verify)
        // ============================================================================
        const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances.length).toBeGreaterThanOrEqual(15) // 15 TEST cases

        // TEST 1: Happy Path - Object literals
        const test1 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 1: Happy Path - Object literals assigned to FlowObject/FlowArray'
        )
        expect(test1).toBeDefined()
        const test1Values = unzipInputArray(test1.values) as any
        const test1Var = (name: string) => test1Values.variables.find((v: any) => v.name === name)?.value
        expect(test1Var('userInfo')).toContain('John Doe')
        expect(test1Var('userInfo')).toContain('john.doe@example.com')
        expect(test1Var('userInfo')).toContain('30')
        expect(test1Var('userInfo')).toContain('true')
        expect(test1Var('tags')).toContain('urgent')
        expect(test1Var('tags')).toContain('important')
        expect(test1Var('tags')).toContain('review')
        expect(test1Var('simpleString')).toBe('Test completed')

        // TEST 2: Datapills in FlowObject fields (verify XML format {{...}})
        const test2 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 2: Datapills used in FlowObject field values'
        )
        expect(test2).toBeDefined()
        const test2Values = unzipInputArray(test2.values) as any
        const test2Var = (name: string) => test2Values.variables.find((v: any) => v.name === name)?.value
        // Datapills are stored in the mapped field within schema
        expect(test2Var('userInfo')).toContain('assigned_to.name')
        expect(test2Var('userInfo')).toContain('assigned_to.email')
        expect(test2Var('userInfo')).toContain('.current.number')
        expect(test2Var('userInfo')).toContain('business_impact')

        // TEST 3: Nested FlowObject with literals
        const test3 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 3: Nested FlowObject with literal values'
        )
        expect(test3).toBeDefined()
        const test3Values = unzipInputArray(test3.values) as any
        const test3Var = (name: string) => test3Values.variables.find((v: any) => v.name === name)?.value
        expect(test3Var('config')).toContain('60')
        expect(test3Var('config')).toContain('5')
        expect(test3Var('config')).toContain('true')
        expect(test3Var('config')).toContain('Production configuration')

        // TEST 4: Nested FlowObject with datapills
        const test4 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 4: Nested FlowObject with datapills in nested fields'
        )
        expect(test4).toBeDefined()
        const test4Values = unzipInputArray(test4.values) as any
        const test4Var = (name: string) => test4Values.variables.find((v: any) => v.name === name)?.value
        expect(test4Var('config')).toContain('.current.priority')
        expect(test4Var('config')).toContain('3')
        expect(test4Var('config')).toContain('short_description')

        // TEST 5: FlowObject with nested FlowArray
        const test5 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 5: FlowObject containing nested FlowArray'
        )
        expect(test5).toBeDefined()
        const test5Values = unzipInputArray(test5.values) as any
        const test5Var = (name: string) => test5Values.variables.find((v: any) => v.name === name)?.value
        expect(test5Var('project')).toContain('Infrastructure Upgrade')
        expect(test5Var('project')).toContain('Setup servers')
        expect(test5Var('project')).toContain('Configure network')
        expect(test5Var('project')).toContain('Deploy apps')

        // TEST 6: Empty and null values
        const test6 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 6: Empty strings, null values, and undefined in FlowObject'
        )
        expect(test6).toBeDefined()
        const test6Values = unzipInputArray(test6.values) as any
        const test6Var = (name: string) => test6Values.variables.find((v: any) => v.name === name)?.value
        expect(test6Var('partialData')).toContain('Has value')
        expect(test6Var('partialData')).toBeDefined()

        // TEST 7: Primitive datapill to FlowObject
        const test7 = flowLogicInstances.find(
            (fl: any) =>
                fl.comment ===
                'TEST 7: Primitive datapill assigned to FlowObject variable (should create empty children)'
        )
        expect(test7).toBeDefined()
        const test7Values = unzipInputArray(test7.values) as any
        const test7Var = (name: string) => test7Values.variables.find((v: any) => v.name === name)?.value
        expect(test7Var('callerData')).toContain('caller_id')

        // TEST 8: Empty FlowArray
        const test8 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 8: Empty array assigned to FlowArray')
        expect(test8).toBeDefined()
        const test8Values = unzipInputArray(test8.values) as any
        const test8Var = (name: string) => test8Values.variables.find((v: any) => v.name === name)?.value
        // Empty arrays are stored as complex objects with schema
        expect(test8Var('emptyList')).toContain('complexObject')
        expect(test8Var('emptyList')).toContain('$COCollectionField')

        // TEST 9: Mixed literals and datapills
        const test9 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 9: FlowObject with mix of literal values and datapills'
        )
        expect(test9).toBeDefined()
        const test9Values = unzipInputArray(test9.values) as any
        const test9Var = (name: string) => test9Values.variables.find((v: any) => v.name === name)?.value
        expect(test9Var('mixedData')).toContain('Static literal value')
        expect(test9Var('mixedData')).toContain('.current.number')
        expect(test9Var('mixedData')).toContain('Incident:')

        // TEST 10: Template expressions
        const test10 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 10: Template expressions in FlowObject fields'
        )
        expect(test10).toBeDefined()
        const test10Values = unzipInputArray(test10.values) as any
        const test10Var = (name: string) => test10Values.variables.find((v: any) => v.name === name)?.value
        expect(test10Var('userInfo')).toContain('User:')
        expect(test10Var('userInfo')).toContain('caller_id')
        expect(test10Var('userInfo')).toContain('@example.com')
        expect(test10Var('userInfo')).toContain('35')

        // TEST 11: Datapills in FlowArray
        const test11 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 11: Datapills inside FlowArray elements'
        )
        expect(test11).toBeDefined()
        const test11Values = unzipInputArray(test11.values) as any
        const test11Var = (name: string) => test11Values.variables.find((v: any) => v.name === name)?.value
        expect(test11Var('tags')).toContain('priority')
        expect(test11Var('tags')).toContain('.current.state')
        expect(test11Var('tags')).toContain('Status:')
        expect(test11Var('tags')).toContain('incident_state')

        // TEST 12: FlowArray with mixed elements
        const test12 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 12: FlowArray with some literal objects and some with datapills'
        )
        expect(test12).toBeDefined()
        const test12Values = unzipInputArray(test12.values) as any
        const test12Var = (name: string) => test12Values.variables.find((v: any) => v.name === name)?.value
        expect(test12Var('tags')).toContain('literal-tag-1')
        expect(test12Var('tags')).toContain('urgency')
        expect(test12Var('tags')).toContain('literal-tag-2')
        expect(test12Var('tags')).toContain('impact')

        // TEST 13: All empty values
        const test13 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 13: FlowObject with all fields empty/null'
        )
        expect(test13).toBeDefined()
        const test13Values = unzipInputArray(test13.values) as any
        const test13Var = (name: string) => test13Values.variables.find((v: any) => v.name === name)?.value
        // All fields are empty/null - just check structure exists
        expect(test13Var('partialData')).toContain('complexObject')
        expect(test13Var('partialData')).toBeDefined()

        // TEST 14: Identifier to FlowObject
        const test14 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 14: Identifier shape (params.trigger.current) assigned to FlowObject'
        )
        expect(test14).toBeDefined()
        const test14Values = unzipInputArray(test14.values) as any
        const test14Var = (name: string) => test14Values.variables.find((v: any) => v.name === name)?.value
        expect(test14Var('callerData')).toContain('.current')

        // TEST 15: Deeply nested property access
        const test15 = flowLogicInstances.find(
            (fl: any) => fl.comment === 'TEST 15: Deeply nested property access in FlowObject'
        )
        expect(test15).toBeDefined()
        const test15Values = unzipInputArray(test15.values) as any
        const test15Var = (name: string) => test15Values.variables.find((v: any) => v.name === name)?.value
        expect(test15Var('config')).toContain('priority')
        expect(test15Var('config')).toContain('urgency')
        expect(test15Var('config')).toContain('active')
        expect(test15Var('config')).toContain('short_description')
    })
})
